using System.Net;using System.Net.Http.Json;using OrdersService.Models;namespace OrdersService.Clients;public sealed class CatalogClient(HttpClient client,ILogger<CatalogClient> logger){public async Task<CatalogLookup> GetSubjectAsync(int id,CancellationToken ct){try{var response=await client.GetAsync($"/api/catalog/subjects/{id}",ct);if(response.StatusCode==HttpStatusCode.NotFound)return new(CatalogLookupStatus.NotFound);response.EnsureSuccessStatusCode();var subject=await response.Content.ReadFromJsonAsync<CatalogSubject>(cancellationToken:ct);return subject is null?new(CatalogLookupStatus.Unavailable):new(CatalogLookupStatus.Found,subject);}catch(Exception ex)when(ex is HttpRequestException or TaskCanceledException){logger.LogWarning(ex,"Catalog lookup failed for subject {SubjectId}",id);return new(CatalogLookupStatus.Unavailable);}}}